package com.projecteden.world.ecology;
import com.projecteden.character.domain.Character;
import jakarta.persistence.*;
@Entity @Table(name="world_terrain_tiles",uniqueConstraints=@UniqueConstraint(columnNames={"character_id","tile_x","tile_y"}))
public class WorldTerrainTile { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="character_id",nullable=false) private Character character; @Column(name="tile_x",nullable=false) private int x; @Column(name="tile_y",nullable=false) private int y; @Enumerated(EnumType.STRING) @Column(nullable=false) private TerrainType terrainType; @Column(nullable=false) private boolean walkable; protected WorldTerrainTile(){} private WorldTerrainTile(Character c,int x,int y,TerrainType t){this.character=c;this.x=x;this.y=y;this.terrainType=t;this.walkable=t.isLandWalkable();} public static WorldTerrainTile create(Character c,int x,int y,TerrainType t){return new WorldTerrainTile(c,x,y,t);} public void changeTerrain(TerrainType t){this.terrainType=t;this.walkable=t.isLandWalkable();} public int getX(){return x;} public int getY(){return y;} public TerrainType getTerrainType(){return terrainType;} public boolean isWalkable(){return walkable;} }
